        after=history_seen[AFTER_MEMBERS['matrix']];provenance=b.doc(history_seen[AFTER_MEMBERS['provenance']])
        if provenance.get('classification')!='DERIVED_POST_PUBLICATION_SNAPSHOT' or provenance.get('target')!='ai/live/support-matrix.json' or provenance.get('targetSHA256')!=AFTER or provenance.get('candidateSHA256')!=AFTER or provenance.get('publicationResultSHA256')!=CLOSED['publicationFiles']['result.json']:raise ValueError('parent-derived after-snapshot target/result/candidate binding differs')
        if b.sha(before)!=BEFORE or b.sha(after)!=AFTER or result.get('matrixBeforeSHA256')!=BEFORE or result.get('matrixAfterSHA256')!=AFTER:raise ValueError('actual before/after publication bytes differ')
        old=b.doc(before);new=b.doc(after);a=old['rows'];z=new['rows'];jev='typesafe-classifier-jev-1.14.0'
        if len(a)!=17 or len(z)!=17 or [r['combo'] for r in a]!=[r['combo'] for r in z] or len({r['combo'] for r in a})!=17 or {k:v for k,v in old.items() if k!='rows'}!={k:v for k,v in new.items() if k!='rows'}:raise ValueError('publication exact17/top-level identity differs')
        changed=[x['combo'] for x,y in zip(a,z) if x!=y]
